 offlineUpload:()=>form('上传线下研讨资料','<div class="field"><label>资料类型</label><select><option>会议纪要</option><option>现场照片</option><option>现场视频</option><option>成果文件</option></select></div><div class="field"><label>文件</label><input value="会议纪要-终稿.docx"></div><div class="field"><label>可见范围</label><select><option>组织方与参会专家</option><option>仅组织方</option></select></div>','上传并归档'),
 comment:()=>form('提交技术文件意见','<div class="field"><label>定位</label><input value="第三章 3.1 第 2 段"></div><div class="field"><label>意见类型</label><select><option>内容修订</option><option>风险提示</option></select></div><div class="field"><label>修改意见</label><textarea placeholder="说明问题并给出建议文本"></textarea></div>'),
 compare:()=>location.hash='versions',confirmVersion:()=>form('确认最终版本','<p>确认 V3.0 内容准确、完整，可作为本届竞赛正式技术文件。确认后将记录电子签认。</p><div class="field"><label>确认意见</label><textarea>同意发布。</textarea></div>','签认并提交'),newQuestion:()=>form('新建竞赛题目',field,'保存题目'),editQuestion:()=>form('编辑题目',field,'保存修改'),submitQuestion:()=>form('提交题目审核','<p>提交后题目将锁定并进入匿名审题流程，确认提交？</p>'),pick:()=>form('从统一题库选题','<div class="field"><label>题目来源</label><select><option>职业认定题库</option><option>历史竞赛题库</option></select></div><div class="question"><input type="checkbox" checked> 铝电解槽电压控制（高级工 · 难）</div><div class="question"><input type="checkbox"> 阳极效应判断（历史竞赛 · 中）</div>','加入赛事题库'),audit:()=>form('题目审核','<div class="question"><b>题干：</b>电解质温度偏高时应优先采取哪项措施？</div><div class="field"><label>审核结果</label><select><option>通过</option><option>退回修改</option><option>不通过</option></select></div><div class="field"><label>审核意见</label><textarea placeholder="准确性、难度、答案与解析意见"></textarea></div>'),
