function toast(t){const x=document.querySelector('#toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),1800)}
const routeNames={'task-detail':'任务详情'};
function render(){const requested=location.hash.slice(1)||'dashboard',key=pages[requested]?requested:'dashboard',item=menu.find(x=>x[1]===key);document.querySelector('#crumb').textContent=item?.[0]||routeNames[key]||menu[0][0];view.innerHTML=pages[key]();document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===key));}
document.addEventListener('click',e=>{const p=e.target.closest('[data-page]'),a=e.target.closest('[data-act]');if(p)location.hash=p.dataset.page;if(a){if(pages[a.dataset.act])location.hash=a.dataset.act;else (action[a.dataset.act]||(()=>toast('操作已记录')))()}if(e.target.closest('[data-close]'))modal.classList.remove('show');if(e.target.closest('[data-confirm]')){const required=[...modal.querySelectorAll('[data-required]')].filter(x=>!x.value.trim());if(required.length){required.forEach(x=>x.style.borderColor='#e5484d');toast('校验失败：请填写必填原因');return}modal.classList.remove('show');toast('提交成功，操作已留痕')}});window.addEventListener('hashchange',render);render();
